const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const n = tok[0], q = tok[1];
const adj = Array.from({ length: n + 1 }, () => []);
for (let i = 0; i < n - 1; i++) {
  const u = tok[2 + 2 * i], v = tok[3 + 2 * i];
  adj[u].push(v); adj[v].push(u);
}
const removed = new Array(n + 1).fill(false), par = new Array(n + 1).fill(0), size = new Array(n + 1).fill(0);
const ancC = Array.from({ length: n + 1 }, () => []), ancD = Array.from({ length: n + 1 }, () => []);
const dist = new Array(n + 1).fill(-1);
const stack = [1];
while (stack.length) {
  const s = stack.pop();
  const comp = [s];
  par[s] = 0;
  for (let h = 0; h < comp.length; h++) {
    const v = comp[h];
    for (const w of adj[v]) if (!removed[w] && w !== par[v]) { par[w] = v; comp.push(w); }
  }
  const total = comp.length;
  for (const v of comp) size[v] = 1;
  for (let i = comp.length - 1; i >= 0; i--) if (par[comp[i]]) size[par[comp[i]]] += size[comp[i]];
  let c = s;
  for (;;) {
    let nxt = 0;
    for (const w of adj[c]) if (!removed[w] && w !== par[c] && size[w] * 2 > total) { nxt = w; break; }
    if (nxt === 0) break;
    c = nxt;
  }
  const bfs = [c];
  dist[c] = 0;
  for (let h = 0; h < bfs.length; h++) {
    const v = bfs[h];
    ancC[v].push(c); ancD[v].push(dist[v]);
    for (const w of adj[v]) if (!removed[w] && dist[w] < 0) { dist[w] = dist[v] + 1; bfs.push(w); }
  }
  for (const v of bfs) dist[v] = -1;
  removed[c] = true;
  for (const w of adj[c]) if (!removed[w]) stack.push(w);
}
const INF = 1e9, best = new Array(n + 1).fill(INF);
function paint(v) {
  for (let i = 0; i < ancC[v].length; i++) if (ancD[v][i] < best[ancC[v][i]]) best[ancC[v][i]] = ancD[v][i];
}
paint(1);
const out = [];
let p = 2 + 2 * (n - 1);
for (let k = 0; k < q; k++) {
  const t = tok[p], v = tok[p + 1];
  p += 2;
  if (t === 1) paint(v);
  else {
    let r = INF;
    for (let i = 0; i < ancC[v].length; i++) r = Math.min(r, best[ancC[v][i]] + ancD[v][i]);
    out.push(r);
  }
}
console.log(out.join("\n"));

