import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedInputStream(System.in));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int q = (int) in.nval;
        List<Integer>[] adj = new List[n + 1];
        for (int i = 0; i <= n; i++) adj[i] = new ArrayList<>();
        for (int i = 0; i < n - 1; i++) {
            in.nextToken(); int u = (int) in.nval;
            in.nextToken(); int v = (int) in.nval;
            adj[u].add(v);
            adj[v].add(u);
        }
        boolean[] removed = new boolean[n + 1];
        int[] par = new int[n + 1], size = new int[n + 1], dist = new int[n + 1];
        Arrays.fill(dist, -1);
        List<int[]>[] anc = new List[n + 1];
        for (int i = 0; i <= n; i++) anc[i] = new ArrayList<>();
        ArrayDeque<Integer> stack = new ArrayDeque<>();
        stack.push(1);
        int[] comp = new int[n];
        while (!stack.isEmpty()) {
            int s = stack.pop();
            int cs = 0;
            comp[cs++] = s;
            par[s] = 0;
            for (int h = 0; h < cs; h++) {
                int v = comp[h];
                for (int w : adj[v]) if (!removed[w] && w != par[v]) { par[w] = v; comp[cs++] = w; }
            }
            int total = cs;
            for (int i = 0; i < cs; i++) size[comp[i]] = 1;
            for (int i = cs - 1; i >= 0; i--) if (par[comp[i]] != 0) size[par[comp[i]]] += size[comp[i]];
            int c = s;
            while (true) {
                int nxt = 0;
                for (int w : adj[c]) if (!removed[w] && w != par[c] && size[w] * 2 > total) { nxt = w; break; }
                if (nxt == 0) break;
                c = nxt;
            }
            int[] bfs = new int[total];
            int bs = 0;
            bfs[bs++] = c;
            dist[c] = 0;
            for (int h = 0; h < bs; h++) {
                int v = bfs[h];
                anc[v].add(new int[]{c, dist[v]});
                for (int w : adj[v]) if (!removed[w] && dist[w] < 0) { dist[w] = dist[v] + 1; bfs[bs++] = w; }
            }
            for (int i = 0; i < bs; i++) dist[bfs[i]] = -1;
            removed[c] = true;
            for (int w : adj[c]) if (!removed[w]) stack.push(w);
        }
        final int INF = 1000000000;
        int[] best = new int[n + 1];
        Arrays.fill(best, INF);
        for (int[] e : anc[1]) best[e[0]] = Math.min(best[e[0]], e[1]);
        StringBuilder out = new StringBuilder();
        for (int k = 0; k < q; k++) {
            in.nextToken(); int t = (int) in.nval;
            in.nextToken(); int v = (int) in.nval;
            if (t == 1) {
                for (int[] e : anc[v]) best[e[0]] = Math.min(best[e[0]], e[1]);
            } else {
                int r = INF;
                for (int[] e : anc[v]) r = Math.min(r, best[e[0]] + e[1]);
                out.append(r).append('\n');
            }
        }
        System.out.print(out);
    }
}

