#include <bits/stdc++.h>
using namespace std;
int main() {
    int n, q;
    scanf("%d %d", &n, &q);
    vector<vector<int>> adj(n + 1);
    for (int i = 0; i < n - 1; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    vector<bool> removed(n + 1, false);
    vector<int> par(n + 1, 0), sz(n + 1, 0), dist(n + 1, -1);
    vector<vector<pair<int, int>>> anc(n + 1);
    vector<int> stk{1};
    while (!stk.empty()) {
        int s = stk.back(); stk.pop_back();
        vector<int> comp{s};
        par[s] = 0;
        for (size_t h = 0; h < comp.size(); h++) {
            int v = comp[h];
            for (int w : adj[v]) if (!removed[w] && w != par[v]) { par[w] = v; comp.push_back(w); }
        }
        int total = comp.size();
        for (int v : comp) sz[v] = 1;
        for (int i = total - 1; i >= 0; i--) if (par[comp[i]]) sz[par[comp[i]]] += sz[comp[i]];
        int c = s;
        while (true) {
            int nxt = 0;
            for (int w : adj[c]) if (!removed[w] && w != par[c] && sz[w] * 2 > total) { nxt = w; break; }
            if (!nxt) break;
            c = nxt;
        }
        vector<int> bfs{c};
        dist[c] = 0;
        for (size_t h = 0; h < bfs.size(); h++) {
            int v = bfs[h];
            anc[v].push_back({c, dist[v]});
            for (int w : adj[v]) if (!removed[w] && dist[w] < 0) { dist[w] = dist[v] + 1; bfs.push_back(w); }
        }
        for (int v : bfs) dist[v] = -1;
        removed[c] = true;
        for (int w : adj[c]) if (!removed[w]) stk.push_back(w);
    }
    const int INF = 1000000000;
    vector<int> best(n + 1, INF);
    auto paint = [&](int v) { for (auto [c, d] : anc[v]) best[c] = min(best[c], d); };
    paint(1);
    while (q--) {
        int t, v;
        scanf("%d %d", &t, &v);
        if (t == 1) paint(v);
        else {
            int r = INF;
            for (auto [c, d] : anc[v]) r = min(r, best[c] + d);
            printf("%d\n", r);
        }
    }
    return 0;
}
